/* mvt.c: this file is part of PolyBench/C */

#include <stdio.h>
#include <unistd.h>
#include <string.h>
#include <math.h>

/* Enable optional OpenMP parallelism when compiled with -fopenmp. */
#ifdef _OPENMP
# include <omp.h>
#endif

/* Include polybench common header. */
#include <polybench.h>

/* Include benchmark-specific header. */
#include "mvt.h"

/* Tunable constants for the optimized kernel.  These do not affect
 * correctness; they only control performance characteristics. */
#ifndef MVT_OMP_MIN_N
/* Below this problem size we avoid spawning OpenMP threads to keep
 * overhead negligible. */
# define MVT_OMP_MIN_N 64
#endif

#ifndef MVT_X2_IBLOCK
/* Blocking factor for the second matrix-vector product.  This is a tile
 * size over the "i" dimension chosen to improve cache locality when
 * accessing A[j][i] (effectively using A row-wise). */
# define MVT_X2_IBLOCK 64
#endif


/* Array initialization. */
static
void init_array(int n,
		DATA_TYPE POLYBENCH_1D(x1,N,n),
		DATA_TYPE POLYBENCH_1D(x2,N,n),
		DATA_TYPE POLYBENCH_1D(y_1,N,n),
		DATA_TYPE POLYBENCH_1D(y_2,N,n),
		DATA_TYPE POLYBENCH_2D(A,N,N,n,n))
{
  int i, j;

  for (i = 0; i < n; i++)
    {
      x1[i] = (DATA_TYPE) (i % n) / n;
      x2[i] = (DATA_TYPE) ((i + 1) % n) / n;
      y_1[i] = (DATA_TYPE) ((i + 3) % n) / n;
      y_2[i] = (DATA_TYPE) ((i + 4) % n) / n;
      for (j = 0; j < n; j++)
	A[i][j] = (DATA_TYPE) (i*j % n) / n;
    }
}


/* DCE code. Must scan the entire live-out data.
   Can be used also to check the correctness of the output. */
static
void print_array(int n,
		 DATA_TYPE POLYBENCH_1D(x1,N,n),
		 DATA_TYPE POLYBENCH_1D(x2,N,n))

{
  int i;

  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("x1");
  for (i = 0; i < n; i++) {
    if (i % 20 == 0) fprintf (POLYBENCH_DUMP_TARGET, "\n");
    fprintf (POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, x1[i]);
  }
  POLYBENCH_DUMP_END("x1");

  POLYBENCH_DUMP_BEGIN("x2");
  for (i = 0; i < n; i++) {
    if (i % 20 == 0) fprintf (POLYBENCH_DUMP_TARGET, "\n");
    fprintf (POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, x2[i]);
  }
  POLYBENCH_DUMP_END("x2");
  POLYBENCH_DUMP_FINISH;
}


/* Main computational kernel. The whole function will be timed,
   including the call and return. */
static
void kernel_mvt[[gnu::flatten, gnu::noinline]](int n,
		DATA_TYPE POLYBENCH_1D(x1,N,n),
		DATA_TYPE POLYBENCH_1D(x2,N,n),
		DATA_TYPE POLYBENCH_1D(y_1,N,n),
		DATA_TYPE POLYBENCH_1D(y_2,N,n),
		DATA_TYPE POLYBENCH_2D(A,N,N,n,n))
{
  /* Local aliases with (where possible) restrict-qualified pointers.
   * This allows the compiler to better optimize and vectorize the code
   * under the assumption that these objects do not alias each other.
   * The actual arguments in this benchmark are distinct allocations,
   * so this does not change program semantics. */
  DATA_TYPE * restrict x1p = x1;
  DATA_TYPE * restrict x2p = x2;
  const DATA_TYPE * restrict y1p = y_1;
  const DATA_TYPE * restrict y2p = y_2;
  DATA_TYPE (* restrict Ap)[n] = A;

  /* PolyBench uses _PB_N as the (possibly reduced) loop bound.  We keep
   * it in a local variable to avoid recomputing the macro. */
  const int n_pb = _PB_N;

  int i, j;

#pragma scop

  /* --------------------------------------------------------------------
   * First matrix-vector operation:
   *   x1[i] = x1[i] + sum_j A[i][j] * y_1[j]
   *
   * Optimizations:
   *   - Parallelize across 'i' (each x1[i] is independent).
   *   - Use a scalar accumulator 'sum' so that x1[i] is loaded once and
   *     stored once, reducing memory traffic and enabling better
   *     vectorization of the inner loop.
   *   - Take a row pointer Ai = Ap[i] to access A row-wise with
   *     contiguous memory accesses.
   * ------------------------------------------------------------------ */
#ifdef _OPENMP
#pragma omp parallel for schedule(static) private(j) if (n_pb >= MVT_OMP_MIN_N)
#endif
  for (i = 0; i < n_pb; i++)
    {
      DATA_TYPE sum = x1p[i];
      DATA_TYPE * restrict Ai = Ap[i]; /* Row i of A: contiguous in j. */

      for (j = 0; j < n_pb; j++)
        sum += Ai[j] * y1p[j];

      x1p[i] = sum;
    }

  /* --------------------------------------------------------------------
   * Second matrix-vector operation:
   *   x2[i] = x2[i] + sum_j A[j][i] * y_2[j]
   *
   * Naively, this accesses A column-wise (varying j in the inner loop),
   * which leads to poor cache behavior on row-major storage.
   *
   * Optimizations:
   *   - Tile the 'i' dimension into blocks of size MVT_X2_IBLOCK.
   *     For each block [ii, i_end), we iterate over all j and then over
   *     the i's in the block:
   *
   *         for ii in 0..n step B
   *           for j in 0..n-1
   *             for i in ii..i_end-1
   *               x2[i] += A[j][i] * y2[j];
   *
   *     For a fixed (i,j) pair, this executes exactly once, so the
   *     computation is identical to the original nested loops.  For a
   *     fixed i, j still increases from 0 to n_pb-1 in order, so the
   *     sequence of floating-point operations on x2[i] is unchanged.
   *
   *   - With this ordering, A is accessed as row j (Ap[j]) and column i
   *     varying fastest, which is contiguous in memory and friendly to
   *     caches and SIMD.
   *
   *   - Parallelize across 'ii' blocks so that each thread updates a
   *     disjoint segment of x2, avoiding any data races.
   * ------------------------------------------------------------------ */
#ifdef _OPENMP
#pragma omp parallel for schedule(static) private(i,j) if (n_pb >= MVT_OMP_MIN_N)
#endif
  for (int ii = 0; ii < n_pb; ii += MVT_X2_IBLOCK)
    {
      int i_end = ii + MVT_X2_IBLOCK;
      if (i_end > n_pb)
        i_end = n_pb;

      for (j = 0; j < n_pb; j++)
        {
          const DATA_TYPE y2j = y2p[j];
          const DATA_TYPE * restrict Aj = Ap[j]; /* Row j of A. */

          /* Inner loop: contiguous traversal of a slice of row j. */
          for (i = ii; i < i_end; i++)
            x2p[i] += Aj[i] * y2j;
        }
    }

#pragma endscop
}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int n = N;

  /* Variable declaration/allocation. */
  POLYBENCH_2D_ARRAY_DECL(A, DATA_TYPE, N, N, n, n);
  POLYBENCH_1D_ARRAY_DECL(x1, DATA_TYPE, N, n);
  POLYBENCH_1D_ARRAY_DECL(x2, DATA_TYPE, N, n);
  POLYBENCH_1D_ARRAY_DECL(y_1, DATA_TYPE, N, n);
  POLYBENCH_1D_ARRAY_DECL(y_2, DATA_TYPE, N, n);


  /* Initialize array(s). */
  init_array (n,
	      POLYBENCH_ARRAY(x1),
	      POLYBENCH_ARRAY(x2),
	      POLYBENCH_ARRAY(y_1),
	      POLYBENCH_ARRAY(y_2),
	      POLYBENCH_ARRAY(A));

  /* Start timer. */
  polybench_start_instruments;

  /* Run kernel. */
  kernel_mvt (n,
	      POLYBENCH_ARRAY(x1),
	      POLYBENCH_ARRAY(x2),
	      POLYBENCH_ARRAY(y_1),
	      POLYBENCH_ARRAY(y_2),
	      POLYBENCH_ARRAY(A));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(n, POLYBENCH_ARRAY(x1), POLYBENCH_ARRAY(x2)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(A);
  POLYBENCH_FREE_ARRAY(x1);
  POLYBENCH_FREE_ARRAY(x2);
  POLYBENCH_FREE_ARRAY(y_1);
  POLYBENCH_FREE_ARRAY(y_2);

  return 0;
}
