  /* Create local `restrict` aliases to help the compiler prove that
     the arrays do not alias one another.  This enables better
     vectorization and allows keeping scalar temporaries in registers
     across the inner loops. */
  DATA_TYPE * __restrict x1p = x1;
  DATA_TYPE * __restrict x2p = x2;
  DATA_TYPE * __restrict y1p = y_1;
  DATA_TYPE * __restrict y2p = y_2;

  /* Treat A as an array of `n`-element rows.  Using a pointer to a
     VLA here keeps indexing natural (Ap[i][j]) while still allowing
     the compiler to optimize for the runtime dimension `n`. */
  DATA_TYPE (* __restrict Ap)[n] = A;

#pragma scop
  /* First matrix-vector multiply:
       x1[i] += sum_j A[i][j] * y_1[j]
     We traverse A by rows (inner index j), which is contiguous in a
     C row-major layout.  x1[i] is kept in a scalar `xi1` for the
     whole inner loop to avoid repeated loads/stores. */
  for (i = 0; i < _PB_N; i++)
    {
      DATA_TYPE xi1 = x1p[i];
      DATA_TYPE * __restrict Ai = Ap[i]; /* current row of A */

      for (j = 0; j < _PB_N; j++)
        xi1 += Ai[j] * y1p[j];

      x1p[i] = xi1;
    }

