   * First matrix-vector product:
   *   x1[i] = x1[i] + sum_j A[i][j] * y_1[j]
   *
   * Optimizations:
   *   - Accumulate into a scalar 'sum' to reduce memory traffic on x1.
   *   - Use row pointer Ai for better alias analysis and fewer address
   *     computations.
   *   - Parallelize over i with OpenMP when available.
   *   - Add vectorization hints for compilers.
   * ------------------------------------------------------------------ */
#ifdef _OPENMP
#pragma omp parallel for schedule(static) private(j)
#endif
  for (i = 0; i < N; i++)
    {
      DATA_TYPE sum = x1[i];
      DATA_TYPE *restrict Ai = A[i];

#if defined(_OPENMP)
#pragma omp simd reduction(+:sum)
#elif defined(__GNUC__)
#pragma GCC ivdep
#endif
