   * Second matrix-vector product:
   *   x2[i] = x2[i] + sum_j A[j][i] * y_2[j]
   *
   * Original code accesses A column-wise (A[j][i]), which is cache
   * unfriendly for a row-major layout.  We restructure the computation
   * to traverse A row-wise:
   *
   *   tmp[i] = sum_j A[j][i] * y_2[j]   (computed using row-wise access)
   *   x2[i] += tmp[i]
   *
   * Parallel OpenMP path:
   *   - Distribute rows j across threads.
   *   - Each thread accumulates into its own private tmp vector to avoid
   *     races: partial_x2[thread][i].
   *   - Afterward, reduce partial_x2 into x2.
   *
   * Sequential path:
   *   - Use a single temporary tmp[i] to accumulate the result, then
   *     add it to x2[i].
   *
   * Both paths compute exactly the same mathematical result; only the
   * accumulation order differs (harmless for this benchmark).
   * ------------------------------------------------------------------ */
#if defined(_OPENMP)

  {
    const int nthreads = omp_get_max_threads();

    /* One partial vector per thread.  Memory overhead is
       nthreads * N * sizeof(DATA_TYPE), which is negligible compared to
       the N x N matrix and well under the +50% constraint. */
    DATA_TYPE *partial_x2 =
      (DATA_TYPE *)polybench_alloc_data((unsigned long long)nthreads *
                                        (unsigned long long)N,
                                        sizeof(DATA_TYPE));

    if (partial_x2 != NULL)
      {
        /* Initialize all partial sums to zero.  */
        memset(partial_x2, 0,
               (size_t)nthreads * (size_t)N * sizeof(DATA_TYPE));

