        {
          const int tid = omp_get_thread_num();
          DATA_TYPE *restrict local =
            partial_x2 + (size_t)tid * (size_t)N;

          /* Distribute rows j across threads; each thread updates its
             own private partial sum vector 'local'. */
#pragma omp for schedule(static)
          for (j = 0; j < N; j++)
            {
              DATA_TYPE y2j = y_2[j];
              DATA_TYPE *restrict Aj = A[j];

#pragma omp simd
              for (i = 0; i < N; i++)
                local[i] += Aj[i] * y2j;
            }
        } /* end parallel region for accumulation */

        /* Reduce all thread-local partial sums into the global x2. */
#pragma omp parallel for schedule(static) private(j)
        for (i = 0; i < N; i++)
          {
            DATA_TYPE sum = x2[i];
            for (j = 0; j < nthreads; j++)
              sum += partial_x2[(size_t)j * (size_t)N + i];
            x2[i] = sum;
          }

        free(partial_x2);
      }
    else
      {
        /* Allocation failed: fall back to the straightforward column-wise
           traversal preserving the original access pattern. */
        for (i = 0; i < N; i++)
          {
            DATA_TYPE sum = x2[i];
#if defined(__GNUC__)
#pragma GCC ivdep
#endif
            for (j = 0; j < N; j++)
              sum += A[j][i] * y_2[j];
            x2[i] = sum;
          }
      }
  }

#else  /* !_OPENMP : sequential but cache-friendly version */

  {
    /* Temporary vector for the A^T * y_2 term. */
    DATA_TYPE *tmp =
      (DATA_TYPE *)polybench_alloc_data((unsigned long long)N,
                                        sizeof(DATA_TYPE));

    if (tmp != NULL)
      {
