        for (i = 0; i < N; i++)
          tmp[i] = (DATA_TYPE)0;

        /* Traverse A row-wise to build tmp = A^T * y_2. */
        for (j = 0; j < N; j++)
          {
            DATA_TYPE y2j = y_2[j];
            DATA_TYPE *restrict Aj = A[j];

#if defined(__GNUC__)
#pragma GCC ivdep
#endif
            for (i = 0; i < N; i++)
              tmp[i] += Aj[i] * y2j;
          }

        /* Add tmp into x2, as required by the original kernel. */
        for (i = 0; i < N; i++)
          x2[i] += tmp[i];

