        for (i = 0; i < N; i++)
          {
            DATA_TYPE sum = x2[i];
#if defined(__GNUC__)
#pragma GCC ivdep
#endif
            for (j = 0; j < N; j++)
              sum += A[j][i] * y_2[j];
            x2[i] = sum;
          }
